def fill_identifiers_from_protocols(apps, schema_editor):
    """OIČ a ID zaměstnání z protokolů ČSSZ k už odeslaným ostrým přihláškám."""
    CsszSubmission = apps.get_model('core', 'CsszSubmission')
    submissions = (CsszSubmission.objects
                   .filter(kind='REGZEC', environment='prod')
                   .exclude(protocol_xml='')
                   .select_related('employee')
                   .order_by('sent_at'))
    for submission in submissions:
        item = _ITEM.search(submission.protocol_xml)
        match = _IDENTIFIER.search(item.group(0)) if item else None
