        employee = submission.employee
        if match.group(2) and not employee.cssz_ikmpsv:
            employee.cssz_ikmpsv = match.group(2)
        if match.group(3) and not employee.cssz_job_id:
            employee.cssz_job_id = match.group(3)
        employee.save(update_fields=['cssz_ikmpsv', 'cssz_job_id'])


